  /**
   * `read`, `reading` or `unreadable`; `null` for a stream asset, whose graph `graph` serves.
   */
  media_facts_state?: string | null;
  /**
   * Why the runtime could not read the asset's bytes, in its own words, while `unreadable`.
   */
