/** Every notification the runtime sends a subscribed connection, by method name: the params it carries. */
export interface ControlNotifications {
  /**
   * A change on the feed of a project the connection subscribed to: a transaction applied, an action refused, media facts read, or files in its folder changed.
   *
   * Since contract version 1, experimental.
   */
  project_changed: ProjectChangedNotificationParams;
  /**
   * A change in the live graph of a stream the connection subscribed to: an edit, a node's new state, a playback change, new drops, raises or link states, or `missed`.
   *
   * Since contract version 2, experimental.
   */
  stream_graph_changed: StreamGraphChangedNotificationParams;
  /**
   * A stream action changed, which `describe_stream_action` describes, or `missed`.
   *
   * Since contract version 2, experimental.
   */
  stream_action_changed: StreamActionChangedNotificationParams;
  /**
   * A project the connection subscribed to has new log records, which `logs` reads on from its cursor, or `missed`.
   *
   * Since contract version 2, experimental.
   */
  project_log_records_written: ProjectLogRecordsWrittenNotificationParams;
}

/** A method name the runtime serves. */
export type ControlOperationMethodName = keyof ControlOperations;

/** A notification method name the runtime sends. */
export type ControlNotificationMethodName = keyof ControlNotifications;

